entries[42187] = { ["name"] = "Pattern: Brilliant Spellthread", ["text"] = "Binds when picked up\nUse: Teaches you how to make Brilliant Spellthread.\nRequires Northrend Tailoring (55)\nRequires Argent Crusade\n- Exalted\nSell Price:\nBrilliant Spellthread\nUse: Permanently embroiders spellthread into pants, increasing spell power by 3 and Versatility by 3.\n\nEnchanting the item causes it to become soulbound. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Eternal Life (4), Iceweb Spider Silk (4), Frozen Orb" }
